import math
import numpy as np

def schedule(n: int) -> list[float]:
    a = 0.65
    nodes = [
        0.5 * (1.0 + a) + 0.5 * (1.0 - a) * math.cos((2 * j + 1) * math.pi / (2 * n))
        for j in range(n)
    ]
    return [float(1.0 / r) for r in reversed(nodes)]

import math
import numpy as np

def schedule(n: int) -> list[float]:
    if n <= 0:
        return []
    base = np.array([1.90, 1.75, 1.60, 1.45, 1.25, 1.00], dtype=float)
    if n == 6:
        return base.tolist()
    return np.interp(
        np.linspace(0.0, 5.0, n),
        np.arange(6, dtype=float),
        base,
    ).tolist()

